sp_widget.client_script:
api.controller = function($scope, $window, $timeout) {

  var c = this;


  /* =====================================================
     INITIAL STATE
     ===================================================== */

  c.sidebarCollapsed = false;

  c.searchText = "";

  c.filters = {
    type: "",
    source: "",
    status: ""
  };

  c.filteredOpportunities = [];

  c.modalOpen = false;

  c.viewModalOpen = false;

  c.isEditMode = false;

  c.selectedOpportunity = null;

  c.saving = false;

  c.saveMessage = "";

  c.toastMessage = "";

  c.toastError = false;


  /* =====================================================
     SAFE DATA
     ===================================================== */

  if (!c.data) {
    c.data = {};
  }

  if (!c.data.opportunities) {
    c.data.opportunities = [];
  }

  if (!c.data.opportunityTypes) {
    c.data.opportunityTypes = [];
  }

  if (!c.data.opportunitySources) {
    c.data.opportunitySources = [];
  }

  if (!c.data.statuses) {
    c.data.statuses = [];
  }

  if (!c.data.companies) {
    c.data.companies = [];
  }

  if (!c.data.summary) {

    c.data.summary = {
      totalOpportunities: 0,
      openOpportunities: 0,
      closedOpportunities: 0,
      totalApplications: 0
    };

  }


  /* =====================================================
     SIDEBAR
     ===================================================== */

  c.toggleSidebar = function() {

    c.sidebarCollapsed =
      !c.sidebarCollapsed;

    if (!$scope.$$phase) {
      $scope.$applyAsync();
    }

  };


  /* =====================================================
     NAVIGATION
     ===================================================== */




  /* =====================================================
     NORMALIZE
     ===================================================== */

  c.normalize = function(value) {

    if (
      value === null ||
      value === undefined
    ) {
      return "";
    }

    return String(value)
      .trim()
      .toLowerCase();

  };


  /* =====================================================
     CHOICE MATCH
     ===================================================== */

  c.choiceMatches = function(
    selectedValue,
    storedValue,
    displayValue
  ) {

    if (!selectedValue) {
      return true;
    }

    var selected =
      c.normalize(selectedValue);

    var stored =
      c.normalize(storedValue);

    var display =
      c.normalize(displayValue);

    return (
      selected === stored ||
      selected === display
    );

  };


  /* =====================================================
     FILTER
     ===================================================== */

  c.getFilteredOpportunities = function() {

    var list =
      c.data.opportunities || [];

    var search =
      c.normalize(c.searchText);


    return list.filter(function(opportunity) {

      var matchesSearch = true;


      if (search) {

        var searchable = [

          opportunity.opportunity_id,

          opportunity.title,

          opportunity.company,

          opportunity.location,

          opportunity.skills,

          opportunity.eligible_branches,

          opportunity.type,

          opportunity.type_value,

          opportunity.source,

          opportunity.source_value,

          opportunity.status,

          opportunity.status_value

        ].join(" ");


        matchesSearch =
          c.normalize(searchable)
            .indexOf(search) !== -1;

      }


      var matchesType =
        c.choiceMatches(
          c.filters.type,
          opportunity.type_value,
          opportunity.type
        );


      var matchesSource =
        c.choiceMatches(
          c.filters.source,
          opportunity.source_value,
          opportunity.source
        );


      var matchesStatus =
        c.choiceMatches(
          c.filters.status,
          opportunity.status_value,
          opportunity.status
        );


      return (
        matchesSearch &&
        matchesType &&
        matchesSource &&
        matchesStatus
      );

    });

  };


  c.updateFilteredOpportunities = function() {

    c.filteredOpportunities =
      c.getFilteredOpportunities();

  };


  /* =====================================================
     CLEAR FILTERS
     ===================================================== */

  c.clearFilters = function() {

    c.searchText = "";

    c.filters.type = "";

    c.filters.source = "";

    c.filters.status = "";

    c.updateFilteredOpportunities();

  };


  /* =====================================================
     WATCH FILTERS
     ===================================================== */

  $scope.$watchGroup(

    [
      function() {
        return c.searchText;
      },

      function() {
        return c.filters.type;
      },

      function() {
        return c.filters.source;
      },

      function() {
        return c.filters.status;
      }
    ],

    function() {

      c.updateFilteredOpportunities();

    }

  );


  /* =====================================================
     INITIAL FILTER
     ===================================================== */

  c.updateFilteredOpportunities();


  /* =====================================================
     INITIALS
     ===================================================== */

  c.getInitials = function(text) {

    if (!text) {
      return "OP";
    }

    var words =
      String(text)
        .trim()
        .split(/\s+/);


    if (words.length === 1) {

      return words[0]
        .substring(0,2)
        .toUpperCase();

    }


    return (
      words[0].charAt(0) +
      words[1].charAt(0)
    ).toUpperCase();

  };


  /* =====================================================
     STATUS CLASS
     ===================================================== */

  c.getStatusClass = function(status) {

    var value =
      c.normalize(status);


    if (
      value === "open" ||
      value === "active"
    ) {

      return "status-open";

    }


    if (
      value === "closed" ||
      value === "inactive" ||
      value === "cancelled" ||
      value === "canceled"
    ) {

      return "status-closed";

    }


    return "status-other";

  };


  /* =====================================================
     RESET FORM
     ===================================================== */

  c.resetForm = function() {

    c.form = {

      sys_id: "",

      opportunity_id: "",

      opportunity_title: "",

      company: "",

      opportunity_type: "",

      opportunity_source: "",

      status: "",

      location: "",

      ctc_stipend: "",

      minimum_cgpa: "",

      eligible_branches: "",

      required_skills: "",

      application_deadline: null,

      drive_date: null,

      job_description: ""

    };

  };


  c.resetForm();


  /* =====================================================
     DATE
     ===================================================== */

  c.toDateTimeLocal = function(value) {

    if (!value) {
      return null;
    }

    var date =
      new Date(value);

    if (isNaN(date.getTime())) {
      return null;
    }

    var year =
      date.getFullYear();

    var month =
      String(date.getMonth() + 1)
        .padStart(2,"0");

    var day =
      String(date.getDate())
        .padStart(2,"0");

    var hours =
      String(date.getHours())
        .padStart(2,"0");

    var minutes =
      String(date.getMinutes())
        .padStart(2,"0");


    return (
      year + "-" +
      month + "-" +
      day + "T" +
      hours + ":" +
      minutes
    );

  };


  /* =====================================================
     CREATE
     ===================================================== */

  c.openAddModal = function() {

    c.resetForm();

    c.isEditMode = false;

    c.saveMessage = "";

    c.modalOpen = true;

  };


  /* =====================================================
     VIEW
     ===================================================== */

  c.openViewModal = function(opportunity) {

    if (!opportunity) {
      return;
    }

    c.selectedOpportunity =
      opportunity;

    c.viewModalOpen = true;

  };


  c.closeViewModal = function() {

    c.viewModalOpen = false;

    c.selectedOpportunity = null;

  };


  c.closeModal = function() {

    if (c.saving) {
      return;
    }

    c.modalOpen = false;

    c.saveMessage = "";

  };


  /* =====================================================
     EDIT
     ===================================================== */

  c.editOpportunity = function(opportunity) {

    if (!opportunity) {
      return;
    }


    c.viewModalOpen = false;

    c.isEditMode = true;

    c.saveMessage = "";


    c.form = {

      sys_id:
        opportunity.sys_id || "",

      opportunity_id:
        opportunity.opportunity_id || "",

      opportunity_title:
        opportunity.title || "",

      company:
        opportunity.company_sys_id || "",

      opportunity_type:
        opportunity.type_value || "",

      opportunity_source:
        opportunity.source_value || "",

      status:
        opportunity.status_value || "",

      location:
        opportunity.location || "",

      ctc_stipend:
        opportunity.ctc || "",

      minimum_cgpa:
        opportunity.minimum_cgpa || "",

      eligible_branches:
        opportunity.eligible_branches || "",

      required_skills:
        opportunity.skills || "",

      application_deadline:
        c.toDateTimeLocal(
          opportunity.application_deadline_raw
        ),

      drive_date:
        c.toDateTimeLocal(
          opportunity.drive_date_raw
        ),

      job_description:
        opportunity.description || ""

    };


    c.modalOpen = true;

  };


  /* =====================================================
     VALIDATION
     ===================================================== */

  c.validateForm = function() {

    if (
      !c.form.opportunity_title ||
      !String(
        c.form.opportunity_title
      ).trim()
    ) {

      c.saveMessage =
        "Opportunity Title is required.";

      return false;

    }


    if (!c.form.company) {

      c.saveMessage =
        "Please select a Company.";

      return false;

    }


    return true;

  };


  /* =====================================================
     SAVE
     ===================================================== */

  c.saveOpportunity = function() {

    c.saveMessage = "";


    if (!c.validateForm()) {
      return;
    }


    c.saving = true;


    var payload = {

      sys_id:
        c.form.sys_id || "",

      opportunity_id:
        c.form.opportunity_id || "",

      opportunity_title:
        c.form.opportunity_title || "",

      company:
        c.form.company || "",

      opportunity_type:
        c.form.opportunity_type || "",

      opportunity_source:
        c.form.opportunity_source || "",

      status:
        c.form.status || "",

      location:
        c.form.location || "",

      ctc_stipend:
        c.form.ctc_stipend || "",

      minimum_cgpa:
        c.form.minimum_cgpa,

      eligible_branches:
        c.form.eligible_branches || "",

      required_skills:
        c.form.required_skills || "",

      application_deadline:
        c.form.application_deadline
          ? new Date(
              c.form.application_deadline
            ).toISOString()
          : "",

      drive_date:
        c.form.drive_date
          ? new Date(
              c.form.drive_date
            ).toISOString()
          : "",

      job_description:
        c.form.job_description || ""

    };


    c.server.get({

      action:
        c.isEditMode
          ? "update"
          : "create",

      opportunity:
        payload

    }).then(

      function(response) {

        var result =
          response.data &&
          response.data.result
            ? response.data.result
            : null;


        if (
          result &&
          result.success
        ) {

          c.modalOpen = false;

          c.saving = false;

          c.showToast(
            c.isEditMode
              ? "Opportunity updated successfully."
              : "Opportunity created successfully.",
            false
          );

          c.refreshData();

        } else {

          c.saving = false;

          c.saveMessage =
            result &&
            result.message
              ? result.message
              : "Unable to save the opportunity.";

        }

      },

      function() {

        c.saving = false;

        c.saveMessage =
          "A server error occurred while saving the opportunity.";

      }

    );

  };


  /* =====================================================
     REFRESH
     ===================================================== */

  c.refreshData = function() {

    c.server.get({

      action: "refresh"

    }).then(

      function(response) {

        if (
          response.data &&
          response.data.opportunities
        ) {

          c.data =
            response.data;

          c.updateFilteredOpportunities();

          c.showToast(
            "Opportunity data refreshed.",
            false
          );

        }

      }

    );

  };


  /* =====================================================
     TOAST
     ===================================================== */

  c.showToast = function(
    message,
    isError
  ) {

    c.toastMessage =
      message;

    c.toastError =
      !!isError;


    if (!$scope.$$phase) {
      $scope.$applyAsync();
    }


    window.setTimeout(

      function() {

        c.toastMessage = "";

        if (!$scope.$$phase) {
          $scope.$applyAsync();
        }

      },

      3500

    );

  };


  /* =====================================================
     DATA WATCH
     ===================================================== */

  $scope.$watch(

    function() {
      return c.data.opportunities;
    },

    function() {

      c.updateFilteredOpportunities();

    },

    true

  );


    c.goTo = function(pageId) {
        if (!pageId) return;
        var map = {
            'dashboard': 'campus360_tpo_home',
            'home': 'campus360_tpo_home',
            'campus360_tpo_home': 'campus360_tpo_home',
            'students': 'campus360_tpo_student_management',
            'student_management': 'campus360_tpo_student_management',
            'campus360_tpo_student_management': 'campus360_tpo_student_management',
            'skills': 'campus360_tpo_skill_intelligence_new',
            'skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence_new': 'campus360_tpo_skill_intelligence_new',
            'assessments': 'student_assessments_new',
            'student_assessments': 'student_assessments_new',
            'student_assessments_new': 'student_assessments_new',
            'companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies_new': 'campus360_tpo_companies_new',
            'opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities_new': 'campus360_tpo_opportunities_new',
            'applications': 'campus360_tpo_application_new',
            'application': 'campus360_tpo_application_new',
            'campus360_tpo_application': 'campus360_tpo_application_new',
            'campus360_tpo_application_new': 'campus360_tpo_application_new',
            'interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews_new': 'campus360_tpo_interviews_new',
            'outcomes': 'campus360_tpo_placement_outcomes',
            'placement_outcomes': 'campus360_tpo_placement_outcomes',
            'campus360_tpo_placement_outcomes': 'campus360_tpo_placement_outcomes',
            'training': 'campus360_tpo_training_programs',
            'training_programs': 'campus360_tpo_training_programs',
            'campus360_tpo_training_programs': 'campus360_tpo_training_programs',
            'enrollments': 'campus360_tpo_training_programs',
            'campus360_tpo_enrollments': 'campus360_tpo_training_programs',
            'mock_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_mock_interviews': 'campus360_tpo_interviews_new',
            'risk': 'campus360_tpo_student_management',
            'campus360_tpo_risk_intelligence': 'campus360_tpo_student_management',
            'interventions': 'campus360_tpo_student_management',
            'campus360_tpo_interventions': 'campus360_tpo_student_management',
            'readiness': 'campus360_tpo_skill_intelligence_new',
            'ai_assistant': 'campus360_tpo_ai_assistant',
            'campus360_tpo_ai_assistant': 'campus360_tpo_ai_assistant'
        };
        var target = map[pageId] || pageId;
        if (typeof $window !== 'undefined' && $window.location) {
            $window.location.href = '?id=' + encodeURIComponent(target);
        } else {
            window.location.href = '?id=' + encodeURIComponent(target);
        }
    };
    c.goToPage = function(pageId) { c.goTo(pageId); };
    c.navigate = function(pageId) { c.goTo(pageId); };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 OPPORTUNITIES
   COMPLETE FINAL CSS
   FULLSCREEN
   NATIVE SERVICENOW NAVBAR HIDDEN
   PROPER CAMPUS360 TOP NAVBAR
   SIDEBAR FOOTER FIXED
   ========================================================= */


/* =========================================================
   1. GLOBAL PAGE RESET
   ========================================================= */

html,
body {
  width:100% !important;
  height:100% !important;

  min-width:100% !important;
  min-height:100% !important;

  margin:0 !important;
  padding:0 !important;

  overflow:hidden !important;

  background:#f7f8fc !important;
}


/* =========================================================
   2. REMOVE SERVICENOW OUTER CONTAINERS
   ========================================================= */

body:has(.campus360-opportunity-app) #sp-page,
body:has(.campus360-opportunity-app) #sp-main,
body:has(.campus360-opportunity-app) .sp-page,
body:has(.campus360-opportunity-app) .sp-main,
body:has(.campus360-opportunity-app) .sp-page-container,
body:has(.campus360-opportunity-app) #page_content,
body:has(.campus360-opportunity-app) .page,
body:has(.campus360-opportunity-app) .page-wrapper,
body:has(.campus360-opportunity-app) .main-content,
body:has(.campus360-opportunity-app) .container,
body:has(.campus360-opportunity-app) .container-fluid,
body:has(.campus360-opportunity-app) .row {
  width:100% !important;
  max-width:none !important;
  min-width:0 !important;

  margin:0 !important;
  padding:0 !important;

  border:0 !important;
}


/* =========================================================
   3. COMPLETELY REMOVE NATIVE SERVICENOW HEADER
   ========================================================= */

body:has(.campus360-opportunity-app) #sp-header,
body:has(.campus360-opportunity-app) header#sp-header,
body:has(.campus360-opportunity-app) .sp-header,
body:has(.campus360-opportunity-app) .sp-header-wrapper,
body:has(.campus360-opportunity-app) .sp-header-content,

body:has(.campus360-opportunity-app) #sp-nav-bar,
body:has(.campus360-opportunity-app) .sp-nav-bar,
body:has(.campus360-opportunity-app) .sp-nav,

body:has(.campus360-opportunity-app) .sp-navbar,
body:has(.campus360-opportunity-app) .sp-navbar-wrapper,
body:has(.campus360-opportunity-app) .sp-navbar-container,

body:has(.campus360-opportunity-app) .portal-header,
body:has(.campus360-opportunity-app) .portal-navbar,
body:has(.campus360-opportunity-app) .portal-nav,
body:has(.campus360-opportunity-app) .header-nav,

body:has(.campus360-opportunity-app) .navpage-header,
body:has(.campus360-opportunity-app) .navpage-header-content,

body:has(.campus360-opportunity-app) .navbar,
body:has(.campus360-opportunity-app) nav.navbar,
body:has(.campus360-opportunity-app) .navbar-default,
body:has(.campus360-opportunity-app) .navbar-inverse,
body:has(.campus360-opportunity-app) .navbar-header,
body:has(.campus360-opportunity-app) .navbar-collapse,

body:has(.campus360-opportunity-app) .navbar-wrapper,
body:has(.campus360-opportunity-app) .sp-navbar-wrapper,
body:has(.campus360-opportunity-app) .sp-header-container,
body:has(.campus360-opportunity-app) .header {
  display:none !important;

  visibility:hidden !important;

  width:0 !important;
  height:0 !important;

  min-width:0 !important;
  min-height:0 !important;

  max-width:0 !important;
  max-height:0 !important;

  margin:0 !important;
  padding:0 !important;

  border:0 !important;

  overflow:hidden !important;
}


/* Hide native header elements except our Campus360 header */

body:has(.campus360-opportunity-app)
header:not(.opportunity-topbar) {
  display:none !important;

  visibility:hidden !important;

  height:0 !important;

  min-height:0 !important;

  max-height:0 !important;

  overflow:hidden !important;
}


/* =========================================================
   4. ROOT CAMPUS360 APPLICATION
   ========================================================= */

.campus360-opportunity-app {
  --purple:#7b3aec;
  --purple-dark:#6424c7;
  --purple-light:#f1e9ff;

  --navy:#121028;

  --text:#17172f;
  --muted:#6b7890;

  --page-bg:#f7f8fc;
  --sidebar-bg:#121028;

  --white:#ffffff;
  --border:#e2e5ec;

  --green:#05976a;
  --green-light:#e9fbf4;

  --orange:#b77900;
  --orange-light:#fff8e6;

  --blue:#2e86ff;
  --blue-light:#eef5ff;

  position:fixed !important;

  top:0 !important;
  left:0 !important;
  right:0 !important;
  bottom:0 !important;

  width:100vw !important;
  height:100vh !important;

  max-width:none !important;
  min-width:0 !important;

  margin:0 !important;
  padding:0 !important;

  background:var(--page-bg);

  color:var(--text);

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    Arial,
    sans-serif;

  overflow:hidden !important;

  z-index:2147483647 !important;

  isolation:isolate;
}


.campus360-opportunity-app *,
.campus360-opportunity-app *::before,
.campus360-opportunity-app *::after {
  box-sizing:border-box;
}


.campus360-opportunity-app button,
.campus360-opportunity-app input,
.campus360-opportunity-app select,
.campus360-opportunity-app textarea {
  font-family:inherit;
}


/* =========================================================
   5. SIDEBAR
   ========================================================= */

.opportunity-sidebar {
  position:absolute !important;

  top:0 !important;
  left:0 !important;
  bottom:0 !important;

  width:250px !important;
  min-width:250px !important;
  max-width:250px !important;

  height:100vh !important;

  margin:0 !important;
  padding:0 !important;

  background:
    linear-gradient(
      180deg,
      #10092a 0%,
      #130d31 55%,
      #0d0822 100%
    ) !important;

  border-right:1px solid #26213f !important;

  color:#ffffff !important;

  z-index:2000 !important;

  display:flex !important;
  flex-direction:column !important;

  overflow:hidden !important;

  transition:
    width .25s ease,
    min-width .25s ease,
    max-width .25s ease,
    transform .25s ease,
    opacity .2s ease;
}


/* =========================================================
   6. SIDEBAR BRAND
   ========================================================= */

.sidebar-brand {
  width:100%;

  height:92px;
  min-height:92px;

  padding:20px;

  display:flex;

  align-items:center;

  flex-shrink:0;

  border-bottom:1px solid #26213f;
}


.brand-icon {
  width:52px;
  height:52px;

  min-width:52px;

  border-radius:15px;

  background:#7b3aec;

  color:#ffffff;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:26px;

  font-weight:900;

  box-shadow:
    0 9px 20px rgba(112,69,232,.20);
}


.brand-text {
  min-width:0;

  margin-left:13px;
}


.brand-title {
  color:#f5f2fb;

  font-size:19px;

  line-height:1;

  font-weight:900;

  white-space:nowrap;
}


.brand-subtitle {
  color:#a9a2bd;

  font-size:11px;

  font-weight:700;

  margin-top:7px;

  letter-spacing:.4px;
}


/* =========================================================
   7. SIDEBAR PROFILE
   ========================================================= */

.sidebar-profile {
  margin:16px 13px 14px;

  padding:14px;

  background:#1c1838;

  border:1px solid #2d2750;

  border-radius:16px;

  display:flex;

  align-items:center;

  flex-shrink:0;
}


.profile-avatar {
  width:47px;
  height:47px;

  min-width:47px;

  border-radius:50%;

  background:#7b3aec;

  color:#ffffff;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:13px;

  font-weight:900;
}


.profile-details {
  min-width:0;

  margin-left:10px;
}


.profile-name {
  color:#f5f2fb;

  font-size:14px;

  font-weight:900;
}


.profile-role {
  color:#b48cff;

  font-size:10px;

  font-weight:900;

  margin-top:2px;
}


.profile-department {
  color:#a9a2bd;

  font-size:9px;

  line-height:1.3;

  margin-top:4px;

  white-space:nowrap;

  overflow:hidden;

  text-overflow:ellipsis;
}


/* =========================================================
   8. SIDEBAR MENU
   IMPORTANT:
   MENU GETS ITS OWN SCROLL AREA.
   FOOTER NO LONGER OVERLAPS NAVIGATION.
   ========================================================= */

.sidebar-menu {
  flex:1 1 auto !important;

  min-height:0 !important;

  width:100%;

  padding:0 13px 10px;

  overflow-y:auto !important;

  overflow-x:hidden !important;

  scrollbar-width:none !important;

  -ms-overflow-style:none !important;
}


.sidebar-menu::-webkit-scrollbar {
  display:none !important;

  width:0 !important;
  height:0 !important;
}


/* =========================================================
   9. SECTION TITLES
   ========================================================= */

.menu-section-title {
  color:#9d96b2;

  font-size:9px;

  font-weight:900;

  letter-spacing:1.5px;

  margin:17px 11px 8px;
}


/* =========================================================
   10. SIDEBAR ITEMS
   ========================================================= */

.sidebar-menu-item {
  width:100%;

  min-height:44px;

  margin:0 0 3px;

  padding:0 12px;

  border:0;

  border-radius:10px;

  background:transparent;

  color:#f5f2fb;

  display:flex;

  align-items:center;

  text-align:left;

  font-size:12px;

  font-weight:700;

  cursor:pointer;

  position:relative;

  z-index:10;

  transition:
    background .16s ease,
    color .16s ease,
    transform .16s ease;
}


.sidebar-menu-item:hover {
  background:#211b40;

  color:#ffffff;

  transform:translateX(1px);
}


.sidebar-menu-item.active {
  background:#7b3aec;

  color:#ffffff;

  box-shadow:
    0 8px 18px rgba(123,58,236,.24);
}


.menu-icon {
  width:27px;

  min-width:27px;

  margin-right:7px;

  color:#aaa3ba;

  font-size:15px;

  text-align:center;
}


.sidebar-menu-item.active .menu-icon {
  color:#ffffff;
}


.menu-label {
  flex:1;

  min-width:0;

  white-space:nowrap;

  overflow:hidden;

  text-overflow:ellipsis;
}


.menu-count {
  min-width:23px;

  height:23px;

  padding:0 6px;

  border-radius:50%;

  background:#2e235a;

  color:#c9b6ff;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:9px;

  font-weight:900;

  flex-shrink:0;
}


.active-count,
.green-count {
  background:#123d32;

  color:#46d6a3;
}


/* =========================================================
   11. SIDEBAR FOOTER
   FIXED BELOW THE SCROLLING MENU
   ========================================================= */

.sidebar-footer {
  width:100%;

  min-height:61px;

  flex:0 0 61px;

  padding:10px 14px 11px;

  border-top:1px solid #26213f;

  background:
    linear-gradient(
      180deg,
      #120c2c 0%,
      #0e0924 100%
    );

  position:relative;

  z-index:50;
}


.sidebar-footer-status {
  display:flex;

  align-items:center;

  gap:7px;

  color:#c7c0da;

  font-size:10px;

  font-weight:800;

  line-height:1;
}


.sidebar-footer-status span {
  width:7px;

  height:7px;

  min-width:7px;

  border-radius:50%;

  background:#3cd18a;

  box-shadow:
    0 0 0 3px rgba(60,209,138,.10);
}


.sidebar-footer small {
  display:block;

  margin-top:5px;

  color:#807896;

  font-size:8px;

  line-height:1;
}


/* =========================================================
   12. MAIN
   ========================================================= */

.opportunity-main {
  position:absolute !important;

  top:0 !important;
  right:0 !important;
  bottom:0 !important;
  left:250px !important;

  width:calc(100vw - 250px) !important;

  height:100vh !important;

  max-width:none !important;

  min-width:0 !important;

  margin:0 !important;

  padding:0 !important;

  background:#f7f8fc !important;

  overflow-x:hidden !important;

  overflow-y:auto !important;

  scrollbar-width:thin;

  scrollbar-color:
    #b8acda
    #f1f2f6;

  z-index:50 !important;

  transition:
    left .25s ease,
    width .25s ease;
}


.opportunity-main::-webkit-scrollbar {
  width:10px !important;

  display:block !important;
}


.opportunity-main::-webkit-scrollbar-track {
  background:#f1f2f6 !important;

  border-left:1px solid #e2e5ec;
}


.opportunity-main::-webkit-scrollbar-thumb {
  background:#b8acda !important;

  border-radius:7px !important;

  border:2px solid #f1f2f6 !important;
}


.opportunity-main::-webkit-scrollbar-thumb:hover {
  background:#957dd1 !important;
}


/* =========================================================
   13. CUSTOM CAMPUS360 TOP NAVBAR
   ========================================================= */

.opportunity-topbar {
  position:sticky !important;

  top:0 !important;

  z-index:1000 !important;

  width:100% !important;

  height:72px !important;

  min-height:72px !important;

  padding:0 22px !important;

  margin:0 !important;

  background:#ffffff !important;

  border-bottom:1px solid #e4e7ed !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  box-shadow:
    0 1px 3px rgba(30,38,55,.025);
}


/* =========================================================
   14. TOPBAR LEFT
   ========================================================= */

.topbar-left {
  min-width:0;

  display:flex;

  align-items:center;

  flex-shrink:1;
}


.sidebar-toggle {
  width:44px !important;

  height:44px !important;

  min-width:44px !important;

  padding:0 !important;

  margin-right:12px !important;

  border:1px solid #dfe3ea !important;

  border-radius:12px !important;

  background:#ffffff !important;

  color:#59667a !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:20px !important;

  line-height:1 !important;

  cursor:pointer !important;

  outline:none !important;

  box-shadow:none !important;
}


.sidebar-toggle:hover {
  background:#f6f1ff !important;

  color:#6d36d9 !important;

  border-color:#d5c6ef !important;
}


.sidebar-toggle:active {
  transform:scale(.95);
}


.page-title-box {
  min-width:0;

  display:flex;

  flex-direction:column;

  justify-content:center;
}


.page-title-small {
  color:#7b3aec;

  font-size:9px;

  font-weight:950;

  letter-spacing:1.7px;

  line-height:1;
}


.page-title-large {
  color:#17172f;

  font-size:17px;

  font-weight:950;

  margin-top:5px;

  line-height:1.1;

  white-space:nowrap;
}


/* =========================================================
   15. TOPBAR RIGHT
   ========================================================= */

.topbar-right {
  min-width:0;

  display:flex;

  align-items:center;

  justify-content:flex-end;

  gap:9px;

  margin-left:auto;

  flex-shrink:0;
}


/* =========================================================
   16. SEARCH BAR
   ========================================================= */

.global-search {
  width:315px !important;

  min-width:230px !important;

  height:42px !important;

  padding:0 13px !important;

  display:flex !important;

  align-items:center !important;

  gap:8px;

  background:#ffffff !important;

  border:1px solid #dfe4ec !important;

  border-radius:11px !important;

  flex-shrink:1;

  transition:
    border-color .15s ease,
    background .15s ease,
    box-shadow .15s ease;
}


.global-search:hover {
  border-color:#d6dbe5 !important;
}


.global-search:focus-within {
  border-color:#a88be8 !important;

  background:#ffffff !important;

  box-shadow:
    0 0 0 3px rgba(123,63,240,.08) !important;
}


.global-search-icon {
  color:#6f3ce0 !important;

  font-size:16px !important;

  line-height:1 !important;

  flex-shrink:0 !important;
}


.global-search input {
  width:100% !important;

  height:100% !important;

  min-width:0 !important;

  margin:0 !important;

  padding:0 !important;

  border:0 !important;

  outline:0 !important;

  background:transparent !important;

  color:#29334a !important;

  font-size:11px !important;

  font-weight:600 !important;

  box-shadow:none !important;
}


.global-search input::placeholder {
  color:#929aaa !important;
}


/* =========================================================
   17. REFRESH BUTTON
   ========================================================= */

.topbar-circle-button {
  position:relative;

  width:42px !important;

  height:42px !important;

  min-width:42px !important;

  padding:0 !important;

  border-radius:50% !important;

  border:1px solid #dfe3eb !important;

  background:#ffffff !important;

  color:#59667a !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:17px !important;

  line-height:1 !important;

  cursor:pointer !important;

  outline:none !important;

  box-shadow:none !important;

  transition:
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    transform .15s ease;
}


.topbar-circle-button i {
  margin:0 !important;

  font-size:17px !important;

  line-height:1 !important;
}


.topbar-circle-button:hover {
  background:#f7f2ff !important;

  border-color:#d1c1f3 !important;

  color:#6736d5 !important;
}


.topbar-circle-button:active {
  transform:scale(.95);
}


/* =========================================================
   18. NOTIFICATION BUTTON
   ========================================================= */

.topbar-icon-button {
  position:relative !important;

  width:42px !important;

  height:42px !important;

  min-width:42px !important;

  padding:0 !important;

  margin:0 !important;

  border-radius:50% !important;

  border:1px solid #dfe3eb !important;

  background:#ffffff !important;

  color:#59667a !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:17px !important;

  line-height:1 !important;

  cursor:pointer !important;

  outline:none !important;

  box-shadow:none !important;

  transition:
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    transform .15s ease;
}


.topbar-icon-button i {
  margin:0 !important;

  padding:0 !important;

  color:inherit !important;

  font-size:17px !important;

  line-height:1 !important;
}


.topbar-icon-button:hover {
  background:#f7f2ff !important;

  border-color:#d1c1f3 !important;

  color:#6736d5 !important;
}


.topbar-icon-button:active {
  transform:scale(.95);
}


/* =========================================================
   19. NOTIFICATION RED DOT
   ========================================================= */

.notification-button .notification-indicator {
  position:absolute !important;

  top:7px !important;

  right:7px !important;

  width:7px !important;

  height:7px !important;

  min-width:7px !important;

  min-height:7px !important;

  padding:0 !important;

  margin:0 !important;

  display:block !important;

  border-radius:50% !important;

  background:#ee4965 !important;

  border:1.5px solid #ffffff !important;

  box-sizing:border-box !important;
}


/* =========================================================
   20. DIVIDER
   ========================================================= */

.topbar-divider {
  width:1px !important;

  height:34px !important;

  margin:0 6px !important;

  background:#e5e8ee !important;

  flex-shrink:0 !important;
}


/* =========================================================
   21. TOPBAR PROFILE
   ========================================================= */

.topbar-user {
  display:flex !important;

  align-items:center !important;

  gap:8px !important;

  margin-left:1px !important;

  flex-shrink:0 !important;
}


.topbar-user-avatar {
  width:40px !important;

  height:40px !important;

  min-width:40px !important;

  border-radius:50% !important;

  background:
    linear-gradient(
      135deg,
      #7c45e8,
      #6d35db
    ) !important;

  color:#ffffff !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:11px !important;

  font-weight:950 !important;

  box-shadow:
    0 4px 10px rgba(123,63,240,.14) !important;
}


.topbar-user-info {
  min-width:0;

  display:flex;

  flex-direction:column;

  justify-content:center;

  gap:2px;
}


.topbar-user-name {
  color:#1d2738 !important;

  font-size:11px !important;

  font-weight:950 !important;

  line-height:1.1 !important;

  white-space:nowrap !important;
}


.topbar-user-role {
  color:#929aaa !important;

  font-size:9px !important;

  font-weight:700 !important;

  line-height:1 !important;

  white-space:nowrap !important;
}


.user-chevron {
  margin-left:2px;

  color:#59667a;

  font-size:14px;

  line-height:1;
}


/* =========================================================
   22. PAGE CONTENT
   ========================================================= */

.opportunity-content {
  width:100% !important;

  max-width:1480px !important;

  margin:0 auto !important;

  padding:27px 30px 48px !important;

  background:#f7f8fc !important;
}


/* =========================================================
   23. PAGE HEADER
   ========================================================= */

.page-header-row {
  width:100%;

  display:flex;

  align-items:flex-end;

  justify-content:space-between;

  gap:25px;

  margin-bottom:22px;
}


.page-header-copy {
  min-width:0;
}


.section-kicker {
  display:flex;

  align-items:center;

  color:#7b3aec;

  font-size:11px;

  font-weight:950;

  letter-spacing:1.4px;

  margin-bottom:8px;
}


.kicker-dot {
  width:8px;

  height:8px;

  min-width:8px;

  border-radius:50%;

  background:#7b3aec;

  margin-right:9px;
}


.page-header-copy h1 {
  margin:0;

  color:#141429;

  font-size:34px;

  line-height:1.05;

  font-weight:950;

  letter-spacing:-.45px;
}


.page-header-copy p {
  margin:9px 0 0;

  max-width:760px;

  color:#737b91;

  font-size:13px;

  font-weight:600;

  line-height:1.55;
}


.page-header-actions {
  display:flex;

  align-items:center;

  gap:9px;

  flex-shrink:0;
}


/* =========================================================
   24. PAGE ACTION BUTTONS
   ========================================================= */

.secondary-action,
.primary-action {
  height:45px;

  padding:0 17px;

  border-radius:10px;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:11px;

  font-weight:900;

  cursor:pointer;

  white-space:nowrap;
}


.secondary-action {
  background:#ffffff;

  border:1px solid #ded7ee;

  color:#6d36d9;
}


.secondary-action:hover {
  background:#faf8ff;

  border-color:#cabbe8;
}


.primary-action {
  background:#7b3aec;

  border:1px solid #7b3aec;

  color:#ffffff;

  box-shadow:
    0 8px 16px rgba(112,69,232,.17);
}


.primary-action:hover {
  background:#692bd2;

  border-color:#692bd2;
}


/* =========================================================
   25. KPI GRID
   ========================================================= */

.opportunity-kpi-grid {
  width:100%;

  display:grid;

  grid-template-columns:
    repeat(4,minmax(0,1fr));

  gap:14px;

  margin-bottom:20px;
}


.opportunity-kpi-card {
  min-height:142px;

  border-radius:16px;

  padding:22px 20px;

  display:flex;

  align-items:center;

  border:1px solid;
}


.kpi-total {
  background:#f5f0ff;

  border-color:#e5d9ff;
}


.kpi-open {
  background:#effcf5;

  border-color:#d2f2e3;
}


.kpi-closed {
  background:#fff8e6;

  border-color:#f3e3b7;
}


.kpi-applications {
  background:#eef5ff;

  border-color:#dbe8fb;
}


.kpi-icon {
  width:56px;

  height:56px;

  min-width:56px;

  border-radius:15px;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:23px;

  font-weight:900;
}


.kpi-total .kpi-icon {
  background:#e5dcff;

  color:#6d36d9;
}


.kpi-open .kpi-icon {
  background:#cff2e1;

  color:#087f5b;
}


.kpi-closed .kpi-icon {
  background:#ffe7b4;

  color:#b77900;
}


.kpi-applications .kpi-icon {
  background:#d8e8ff;

  color:#2e86ff;
}


.kpi-content {
  min-width:0;

  margin-left:15px;
}


.kpi-label {
  color:#273047;

  font-size:9px;

  font-weight:950;

  letter-spacing:1.2px;

  line-height:1.25;
}


.kpi-value {
  margin-top:7px;

  font-size:28px;

  line-height:1;

  font-weight:950;
}


.kpi-total .kpi-value {
  color:#6424c7;
}


.kpi-open .kpi-value {
  color:#087f5b;
}


.kpi-closed .kpi-value {
  color:#b77900;
}


.kpi-applications .kpi-value {
  color:#2e86ff;
}


.kpi-description {
  color:#737b91;

  font-size:9px;

  font-weight:600;

  margin-top:7px;
}


/* =========================================================
   26. FILTER CARD
   ========================================================= */

.opportunity-filter-card {
  width:100%;

  background:#ffffff;

  border:1px solid #e2e5ec;

  border-radius:15px;

  padding:11px;

  margin-bottom:17px;
}


.filter-controls {
  width:100%;

  display:flex;

  align-items:center;

  gap:8px;
}


.search-box {
  flex:2 1 320px;

  min-width:220px;

  height:45px;

  display:flex;

  align-items:center;

  border:1px solid #e1e5ec;

  border-radius:9px;

  padding:0 12px;

  background:#ffffff;
}


.search-icon {
  color:#7b3aec;

  font-size:18px;

  margin-right:7px;
}


.search-box input {
  width:100%;

  border:0;

  outline:0;

  background:transparent;

  color:#273047;

  font-size:12px;
}


.search-box:focus-within {
  border-color:#b99af7;

  box-shadow:
    0 0 0 3px rgba(123,58,236,.08);
}


.filter-select {
  flex:1 1 165px;

  min-width:135px;

  height:45px;

  border:1px solid #e1e5ec;

  border-radius:9px;

  background:#ffffff;

  color:#28364e;

  padding:0 10px;

  font-size:11px;

  font-weight:800;

  outline:0;
}


.filter-select:focus {
  border-color:#b99af7;

  box-shadow:
    0 0 0 3px rgba(123,58,236,.08);
}


.clear-filter-btn {
  flex:0 0 65px;

  height:45px;

  border:1px solid #e1e5ec;

  border-radius:9px;

  background:#ffffff;

  color:#59657a;

  font-size:11px;

  font-weight:900;

  cursor:pointer;
}


.clear-filter-btn:hover {
  background:#f7f5fb;

  color:#6d36d9;
}


/* =========================================================
   27. OPPORTUNITY DIRECTORY
   ========================================================= */

.opportunity-directory-card {
  width:100%;

  background:#ffffff;

  border:1px solid #dddff0;

  border-radius:16px;

  overflow:hidden;

  box-shadow:
    0 2px 8px rgba(30,25,60,.035);
}


.opportunity-directory-card::before {
  content:"";

  display:block;

  width:100%;

  height:4px;

  background:
    linear-gradient(
      90deg,
      #7b3aec 0%,
      #7b3aec 28%,
      #2e86ff 28%,
      #2e86ff 48%,
      #05976a 48%,
      #05976a 68%,
      #f2b632 68%,
      #f2b632 84%,
      #ef476f 84%,
      #ef476f 100%
    );
}


/* =========================================================
   28. DIRECTORY HEADER
   ========================================================= */

.directory-header {
  min-height:82px;

  padding:16px 19px;

  display:flex;

  align-items:center;

  justify-content:space-between;

  background:
    linear-gradient(
      90deg,
      #faf7ff 0%,
      #ffffff 62%
    );

  border-bottom:1px solid #e7e3f2;
}


.directory-kicker {
  color:#7b3aec;

  font-size:8px;

  font-weight:950;

  letter-spacing:1.4px;

  margin-bottom:5px;
}


.directory-header h2 {
  margin:0;

  color:#141429;

  font-size:21px;

  font-weight:950;
}


.directory-header-right {
  display:flex;

  align-items:center;

  gap:12px;
}


.record-count {
  color:#6d36d9;

  font-size:11px;

  font-weight:800;

  padding:7px 10px;

  border-radius:20px;

  background:#f3efff;

  border:1px solid #ded1f7;
}


.directory-add-btn {
  height:38px;

  padding:0 14px;

  border:0;

  border-radius:9px;

  background:#7b3aec;

  color:#ffffff;

  font-size:11px;

  font-weight:900;

  cursor:pointer;

  box-shadow:
    0 5px 12px rgba(123,58,236,.16);
}


.directory-add-btn:hover {
  background:#692bd2;
}


/* =========================================================
   29. TABLE
   ========================================================= */

.opportunity-table-wrapper {
  width:100%;

  max-height:calc(100vh - 400px);

  min-height:270px;

  overflow-x:auto;

  overflow-y:auto;
}


.opportunity-table-wrapper::-webkit-scrollbar {
  width:8px;

  height:8px;
}


.opportunity-table-wrapper::-webkit-scrollbar-track {
  background:#f7f8fb;
}


.opportunity-table-wrapper::-webkit-scrollbar-thumb {
  background:#bdb4d2;

  border-radius:8px;
}


.opportunity-table {
  width:100%;

  min-width:1380px;

  border-collapse:collapse;

  table-layout:fixed;
}


.opportunity-table thead th {
  position:sticky;

  top:0;

  z-index:20;

  background:#fafbfe;

  color:#737b91;

  font-size:8px;

  font-weight:950;

  letter-spacing:1px;

  text-align:left;

  padding:13px 14px;

  border-bottom:1px solid #e5e8ee;

  white-space:nowrap;
}


.opportunity-table thead th:nth-child(1) {
  color:#6d36d9;
}


.opportunity-table thead th:nth-child(2) {
  color:#7b3aec;
}


.opportunity-table thead th:nth-child(3) {
  color:#2e6fc5;
}


.opportunity-table thead th:nth-child(4) {
  color:#b77900;
}


.opportunity-table thead th:nth-child(5),
.opportunity-table thead th:nth-child(6) {
  color:#087f5b;
}


.opportunity-table thead th:nth-child(7) {
  color:#6d36d9;
}


.opportunity-table thead th:nth-child(8) {
  color:#2e86ff;
}


.opportunity-table thead th:nth-child(9) {
  color:#b77900;
}


.opportunity-table thead th:nth-child(10) {
  color:#087f5b;
}


.opportunity-table thead th:nth-child(11) {
  color:#6d36d9;
}


.opportunity-table tbody tr {
  transition:background .15s ease;
}


.opportunity-table tbody tr:hover td {
  background:#fbf9ff;
}


.opportunity-table tbody td {
  padding:14px;

  border-bottom:1px solid #edf0f4;

  vertical-align:middle;

  color:#39445a;

  font-size:11px;

  background:#ffffff;
}


/* =========================================================
   30. OPPORTUNITY NAME
   ========================================================= */

.opportunity-name-cell {
  min-width:250px;

  display:flex;

  align-items:center;
}


.opportunity-avatar {
  width:39px;

  height:39px;

  min-width:39px;

  border-radius:11px;

  background:
    linear-gradient(
      135deg,
      #eee5ff 0%,
      #dfd0ff 100%
    );

  color:#6d36d9;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:10px;

  font-weight:950;

  flex-shrink:0;

  margin-right:10px;

  border:1px solid #d8c8fa;
}


.opportunity-title {
  max-width:250px;

  color:#17172f;

  font-size:12px;

  font-weight:950;
}


.opportunity-title:hover {
  color:#6d36d9;
}


.opportunity-subtitle {
  color:#8a92a5;

  font-size:9px;

  margin-top:3px;
}


/* =========================================================
   31. TABLE VALUES
   ========================================================= */

.opportunity-id {
  color:#6d36d9;

  font-size:10px;

  font-weight:950;

  background:#f3edff;

  padding:5px 7px;

  border-radius:7px;

  display:inline-flex;
}


.company-name {
  color:#273047;

  font-weight:850;
}


.type-badge {
  display:inline-flex;

  padding:5px 8px;

  border-radius:8px;

  background:#fff6dc;

  color:#a96d00;

  border:1px solid #f2dfaa;

  font-size:9px;

  font-weight:950;
}


.location-text {
  color:#087f5b;

  font-weight:800;

  background:#effaf5;

  padding:5px 8px;

  border-radius:7px;
}


.ctc-text {
  color:#087f5b;

  font-weight:950;

  background:#e9fbf4;

  padding:5px 8px;

  border-radius:7px;
}


.cgpa-value {
  color:#6040bb;

  font-weight:950;
}


.application-count {
  display:flex;

  flex-direction:column;
}


.application-number {
  color:#2e86ff;

  font-size:13px;

  font-weight:950;
}


.application-label {
  color:#8a92a5;

  font-size:8px;
}


.date-text {
  color:#a96d00;

  font-size:10px;

  font-weight:850;

  background:#fff8e8;

  padding:5px 8px;

  border-radius:7px;
}


/* =========================================================
   32. STATUS
   ========================================================= */

.status-badge {
  display:inline-flex;

  min-width:66px;

  padding:5px 9px;

  border-radius:20px;

  align-items:center;

  justify-content:center;

  font-size:9px;

  font-weight:950;
}


.status-open {
  background:#e5f8ef;

  color:#087f5b;

  border:1px solid #bfead7;
}


.status-closed {
  background:#fff0f0;

  color:#c53b52;

  border:1px solid #f3cfd5;
}


.status-other {
  background:#f1ebff;

  color:#6745b4;

  border:1px solid #ded0fa;
}


/* =========================================================
   33. VIEW BUTTON
   ========================================================= */

.view-button {
  height:32px;

  padding:0 12px;

  border-radius:8px;

  border:1px solid #d7c8f2;

  background:#f8f4ff;

  color:#6d36d9;

  font-size:9px;

  font-weight:950;

  cursor:pointer;

  transition:
    background .15s ease,
    color .15s ease,
    border-color .15s ease,
    transform .15s ease;
}


.view-button:hover {
  background:#7b3aec;

  color:#ffffff;

  border-color:#7b3aec;

  transform:translateY(-1px);
}


/* =========================================================
   34. EMPTY STATE
   ========================================================= */

.empty-state {
  height:210px !important;

  text-align:center !important;

  vertical-align:middle !important;
}


.empty-icon {
  width:42px;

  height:42px;

  margin:0 auto 8px;

  border-radius:12px;

  background:#f1e9ff;

  color:#7b3aec;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:18px;
}


.empty-title {
  color:#32384b;

  font-size:11px;

  font-weight:900;
}


.empty-description {
  margin-top:4px;

  color:#8c95a8;

  font-size:9px;
}


/* =========================================================
   35. MODAL BACKDROP
   ========================================================= */

.modal-backdrop {
  position:fixed !important;

  inset:0 !important;

  z-index:2147483646 !important;

  background:rgba(17,29,48,.62) !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  padding:20px !important;

  overflow-y:auto !important;
}


/* =========================================================
   36. CREATE / EDIT MODAL
   ========================================================= */

.opportunity-modal {
  width:min(1050px,96vw) !important;

  height:min(90vh,900px) !important;

  max-height:90vh !important;

  min-height:0 !important;

  background:#ffffff !important;

  border-radius:19px !important;

  overflow:hidden !important;

  box-shadow:
    0 30px 90px rgba(15,28,50,.34) !important;

  display:flex !important;

  flex-direction:column !important;

  flex-shrink:0 !important;
}


.modal-header {
  flex:0 0 auto !important;

  padding:21px 26px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  border-bottom:1px solid #e2dff0 !important;

  background:
    linear-gradient(
      110deg,
      #f1e9ff 0%,
      #fbf9ff 55%,
      #ffffff 100%
    ) !important;
}


.modal-title-area {
  display:flex;

  align-items:center;
}


.modal-icon {
  width:53px;

  height:53px;

  border-radius:15px;

  background:#d6c2ff;

  color:#6d36d9;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:27px;

  font-weight:950;

  margin-right:14px;

  box-shadow:
    inset 0 0 0 1px #cdbcf5;
}


.modal-kicker {
  color:#7b3aec;

  font-size:9px;

  font-weight:950;

  letter-spacing:1.5px;

  margin-bottom:5px;
}


.modal-header h2 {
  color:#141429;

  font-size:25px;

  font-weight:950;

  line-height:1.1;

  margin:0;
}


.modal-header p {
  color:#737b91;

  font-size:12px;

  font-weight:600;

  margin:5px 0 0;
}


.modal-close {
  width:41px;

  height:41px;

  border-radius:11px;

  border:1px solid #d7dce5;

  background:#ffffff;

  color:#59657a;

  font-size:24px;

  cursor:pointer;
}


.modal-close:hover {
  background:#f2edff;

  color:#7b3aec;

  border-color:#c9b7ed;
}


/* =========================================================
   37. MODAL BODY
   ========================================================= */

.modal-body {
  flex:1 1 auto !important;

  min-height:0 !important;

  overflow-y:auto !important;

  overflow-x:hidden !important;

  padding:22px 26px 28px !important;

  background:#ffffff !important;
}


.modal-body::-webkit-scrollbar,
.view-modal-body::-webkit-scrollbar {
  width:8px;
}


.modal-body::-webkit-scrollbar-thumb,
.view-modal-body::-webkit-scrollbar-thumb {
  background:#b9a7e8;

  border-radius:10px;
}


.modal-body::-webkit-scrollbar-track,
.view-modal-body::-webkit-scrollbar-track {
  background:#f7f5fb;
}


/* =========================================================
   38. FORM SECTIONS
   ========================================================= */

.form-section-title {
  font-size:9px;

  font-weight:950;

  letter-spacing:1.5px;

  padding:9px 12px;

  margin:2px 0 15px;

  border-radius:8px;
}


.purple-section {
  color:#6741c9;

  background:#f0eaff;

  border-left:4px solid #7b3aec;
}


.green-section {
  color:#087f5b;

  background:#e9fbf4;

  border-left:4px solid #05976a;
}


.blue-section {
  color:#2e6fc5;

  background:#e8f2ff;

  border-left:4px solid #3b82f6;
}


/* =========================================================
   39. FORM GRID
   ========================================================= */

.form-grid {
  display:grid;

  grid-template-columns:
    repeat(2,minmax(0,1fr));

  gap:15px;

  margin-bottom:22px;
}


.form-group-wide,
.form-group-full {
  grid-column:1 / -1;
}


.form-group label {
  display:block;

  color:#344158;

  font-size:11px;

  font-weight:900;

  margin-bottom:6px;
}


.form-group label span {
  color:#c53b52;
}


.form-group input,
.form-group textarea,
.modal-select {
  width:100%;

  border:1px solid #dfe3ea;

  border-radius:9px;

  background:#fbfcfe;

  color:#20263a;

  outline:none;

  font-size:12px;

  font-weight:650;

  box-shadow:none;
}


.form-group input,
.modal-select {
  height:44px;

  padding:0 11px;
}


.form-group textarea {
  min-height:125px;

  padding:11px;

  resize:vertical;
}


.form-group input:focus,
.form-group textarea:focus,
.modal-select:focus {
  background:#ffffff;

  border-color:#9a6bff;

  box-shadow:
    0 0 0 3px rgba(112,69,232,.10);
}


/* =========================================================
   40. MODAL FOOTER
   ========================================================= */

.modal-footer {
  flex:0 0 auto !important;

  min-height:70px;

  padding:13px 26px;

  border-top:1px solid #e2e6ed;

  display:flex;

  align-items:center;

  justify-content:flex-end;

  gap:9px;

  background:#f8f9fc;
}


.modal-message {
  margin-right:auto;

  color:#c53b52;

  font-size:11px;

  font-weight:800;
}


.modal-cancel-btn,
.modal-save-btn {
  height:41px;

  padding:0 18px;

  border-radius:9px;

  font-size:11px;

  font-weight:900;

  cursor:pointer;
}


.modal-cancel-btn {
  border:1px solid #dfe3ea;

  background:#ffffff;

  color:#59657a;
}


.modal-save-btn {
  border:1px solid #7b3aec;

  background:#7b3aec;

  color:#ffffff;

  box-shadow:
    0 7px 15px rgba(112,69,232,.18);
}


.modal-save-btn:hover {
  background:#6424c7;

  border-color:#6424c7;
}


/* =========================================================
   41. VIEW MODAL
   ========================================================= */

.view-modal {
  width:min(1040px,96vw) !important;

  height:min(88vh,880px) !important;

  max-height:88vh !important;

  min-height:0 !important;

  background:#ffffff !important;

  border-radius:19px !important;

  overflow:hidden !important;

  box-shadow:
    0 30px 90px rgba(15,28,50,.38) !important;

  display:flex !important;

  flex-direction:column !important;

  flex-shrink:0 !important;
}


.view-modal-header {
  flex:0 0 auto !important;

  min-height:130px;

  padding:23px 31px;

  display:flex;

  align-items:center;

  justify-content:space-between;

  border-bottom:1px solid #e2dff0;

  background:
    linear-gradient(
      110deg,
      #f1e9ff 0%,
      #faf9ff 58%,
      #ffffff 100%
    );
}


.view-title-area {
  display:flex;

  align-items:center;
}


.view-opportunity-icon {
  width:60px;

  height:60px;

  min-width:60px;

  border-radius:16px;

  background:#e7dcff;

  color:#6d36d9;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:14px;

  font-weight:950;

  margin-right:15px;

  border:1px solid #cdbcf5;
}


.view-modal-header h2 {
  color:#141429;

  font-size:28px;

  font-weight:950;

  line-height:1.1;

  margin:0 0 9px;
}


.view-header-meta {
  display:flex;

  align-items:center;

  gap:8px;
}


.view-id-pill {
  display:inline-flex;

  align-items:center;

  min-height:25px;

  padding:0 9px;

  border-radius:7px;

  background:#eee8ff;

  color:#6d36d9;

  font-size:9px;

  font-weight:950;
}


/* =========================================================
   42. VIEW BODY
   ========================================================= */

.view-modal-body {
  flex:1 1 auto !important;

  min-height:0 !important;

  overflow-y:auto !important;

  overflow-x:hidden !important;

  padding:21px 31px 29px !important;

  background:#f7f8fc !important;
}


.view-section-title {
  font-size:9px;

  font-weight:950;

  letter-spacing:1.4px;

  padding:8px 11px;

  border-radius:8px;

  margin:2px 0 12px;
}


.purple-view-title {
  color:#6540c5;

  background:#f2edff;

  border-left:4px solid #7b3aec;
}


.green-view-title {
  color:#087f5b;

  background:#e5f6ee;

  border-left:4px solid #05976a;

  margin-top:20px;
}


.blue-view-title {
  color:#2e6fc5;

  background:#e7f1fd;

  border-left:4px solid #3b82f6;

  margin-top:20px;
}


/* =========================================================
   43. DETAIL GRID
   ========================================================= */

.details-grid {
  display:grid;

  grid-template-columns:
    repeat(2,minmax(0,1fr));

  gap:10px;
}


.detail-box {
  position:relative;

  min-height:82px;

  padding:14px 15px 13px 18px;

  border-radius:11px;

  background:#ffffff;

  border:1px solid #dfe5ed;

  overflow:hidden;
}


.detail-box::before {
  content:"";

  position:absolute;

  left:0;

  top:0;

  bottom:0;

  width:4px;
}


.detail-purple::before {
  background:#7b3aec;
}


.detail-green::before {
  background:#05976a;
}


.detail-blue::before {
  background:#3b82f6;
}


.detail-orange::before {
  background:#e3a43a;
}


.detail-box span {
  display:block;

  color:#7b879a;

  font-size:8px;

  font-weight:950;

  letter-spacing:.9px;

  margin-bottom:7px;
}


.detail-box strong {
  color:#273047;

  font-size:13px;

  font-weight:900;

  line-height:1.4;
}


.detail-purple strong {
  color:#6040bb;
}


.detail-green strong {
  color:#087f5b;
}


.detail-blue strong {
  color:#2e6fc5;
}


.detail-orange strong {
  color:#ad720f;
}


.detail-wide {
  grid-column:1 / -1;
}


.detail-description {
  min-height:125px;
}


.detail-box p {
  margin:0;

  color:#59657a;

  font-size:12px;

  line-height:1.6;

  font-weight:600;
}


/* =========================================================
   44. VIEW FOOTER
   ========================================================= */

.view-modal-footer {
  flex:0 0 auto !important;

  min-height:68px;

  padding:13px 31px;

  border-top:1px solid #dfe5ed;

  display:flex;

  align-items:center;

  justify-content:flex-end;

  gap:9px;

  background:#ffffff;
}


/* =========================================================
   45. TOAST
   ========================================================= */

.opportunity-toast {
  position:fixed !important;

  right:24px !important;

  bottom:24px !important;

  z-index:2147483647 !important;

  min-width:250px;

  padding:13px 17px;

  border-radius:10px;

  background:#173f34;

  color:#ffffff;

  font-size:11px;

  font-weight:800;

  box-shadow:
    0 12px 28px rgba(20,25,30,.18);
}


.opportunity-toast.toast-error {
  background:#8f3434;
}


/* =========================================================
   46. AI WIDGET
   ========================================================= */

.campus360-ai-widget {
  position:fixed !important;

  right:21px !important;

  bottom:18px !important;

  z-index:2147483645 !important;

  pointer-events:auto;
}


/* =========================================================
   47. COLLAPSED SIDEBAR
   ========================================================= */

.campus360-opportunity-app.sidebar-collapsed
.opportunity-sidebar {
  width:0 !important;

  min-width:0 !important;

  max-width:0 !important;

  transform:translateX(-100%) !important;

  opacity:0 !important;

  pointer-events:none !important;

  overflow:hidden !important;

  border-right:0 !important;
}


.campus360-opportunity-app.sidebar-collapsed
.opportunity-main {
  left:0 !important;

  width:100vw !important;
}


/* =========================================================
   48. MEDIUM DESKTOP
   ========================================================= */

@media (max-width:1250px) {

  .global-search {
    width:250px !important;

    min-width:190px !important;
  }


  .filter-controls {
    flex-wrap:wrap;
  }


  .search-box {
    flex:1 1 100%;
  }

}


/* =========================================================
   49. TABLET
   ========================================================= */

@media (max-width:1000px) {

  .opportunity-sidebar {
    width:220px !important;

    min-width:220px !important;

    max-width:220px !important;
  }


  .opportunity-main {
    left:220px !important;

    width:calc(100vw - 220px) !important;
  }


  .campus360-opportunity-app.sidebar-collapsed
  .opportunity-main {
    left:0 !important;

    width:100% !important;
  }


  .opportunity-content {
    padding-left:20px !important;

    padding-right:20px !important;
  }


  .page-header-row {
    align-items:flex-start;

    flex-direction:column;
  }


  .page-header-actions {
    width:100%;

    justify-content:flex-start;
  }


  .opportunity-kpi-grid {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }

}


/* =========================================================
   50. SMALL TABLET
   ========================================================= */

@media (max-width:800px) {

  .opportunity-sidebar {
    width:76px !important;

    min-width:76px !important;

    max-width:76px !important;
  }


  .opportunity-main {
    left:76px !important;

    width:calc(100vw - 76px) !important;
  }


  .brand-text,
  .profile-details,
  .menu-section-title,
  .menu-label,
  .menu-count {
    display:none !important;
  }


  .sidebar-brand {
    justify-content:center;

    padding-left:8px;

    padding-right:8px;
  }


  .sidebar-profile {
    justify-content:center;

    margin-left:8px;

    margin-right:8px;

    padding-left:8px;

    padding-right:8px;
  }


  .sidebar-menu-item {
    justify-content:center;

    padding-left:8px;

    padding-right:8px;
  }


  .menu-icon {
    margin-right:0;
  }


  .sidebar-footer {
    padding-left:7px;

    padding-right:7px;
  }


  .sidebar-footer-status {
    justify-content:center;
  }


  .sidebar-footer-status span {
    margin:0;
  }


  .sidebar-footer-status {
    font-size:0;
  }


  .sidebar-footer small {
    display:none;
  }


  .global-search {
    width:185px !important;

    min-width:145px !important;
  }


  .topbar-user-info,
  .user-chevron {
    display:none;
  }


  .page-header-copy h1 {
    font-size:29px;
  }


  .form-grid,
  .details-grid {
    grid-template-columns:1fr !important;
  }


  .form-group-wide,
  .form-group-full,
  .detail-wide {
    grid-column:auto !important;
  }

}


/* =========================================================
   51. MOBILE
   ========================================================= */

@media (max-width:560px) {

  .opportunity-sidebar {
    width:0 !important;

    min-width:0 !important;

    max-width:0 !important;

    transform:translateX(-100%) !important;

    overflow:hidden !important;
  }


  .opportunity-main {
    left:0 !important;

    width:100vw !important;
  }


  .opportunity-topbar {
    height:68px !important;

    min-height:68px !important;

    padding:0 12px !important;
  }


  .page-title-small {
    display:none;
  }


  .page-title-large {
    font-size:14px;
  }


  .global-search {
    display:none !important;
  }


  .topbar-divider {
    display:none !important;
  }


  .topbar-user-info,
  .user-chevron {
    display:none !important;
  }


  .opportunity-content {
    padding:
      18px
      10px
      36px !important;
  }


  .page-header-copy h1 {
    font-size:25px;
  }


  .page-header-copy p {
    font-size:11px;
  }


  .page-header-actions {
    width:100%;

    flex-direction:column;

    align-items:stretch;
  }


  .secondary-action,
  .primary-action {
    width:100%;
  }


  .opportunity-kpi-grid {
    grid-template-columns:1fr;
  }


  .filter-controls {
    flex-direction:column;

    align-items:stretch;
  }


  .search-box,
  .filter-select,
  .clear-filter-btn {
    width:100%;

    min-width:0;

    flex:1 1 auto;
  }


  .directory-header {
    flex-direction:column;

    align-items:flex-start;

    gap:10px;
  }


  .directory-header-right {
    width:100%;

    justify-content:space-between;
  }


  .opportunity-table-wrapper {
    max-height:calc(100vh - 350px);
  }


  .opportunity-toast {
    left:12px;

    right:12px;

    min-width:0;
  }

}

sp_widget.script:
(function() {


  /* =====================================================
     TABLE NAMES
     ===================================================== */

  var OPPORTUNITY_TABLE =
    "x_snc_campus360_placement_opportunity";

  var COMPANY_TABLE =
    "x_snc_campus360_company_master";

  var APPLICATION_TABLE =
    "x_snc_campus360_student_application";


  /* =====================================================
     INITIAL DATA
     ===================================================== */

  data.opportunities = [];

  data.companies = [];

  data.opportunityTypes = [];

  data.opportunitySources = [];

  data.statuses = [];


  data.summary = {

    totalOpportunities: 0,

    openOpportunities: 0,

    closedOpportunities: 0,

    totalApplications: 0

  };


  data.companyCount = 0;

  data.applicationCount = 0;

  data.studentCount = 0;

  data.placementOutcomeCount = 0;

  data.riskCount = 0;

  data.result = null;


  /* =====================================================
     CHOICE LABEL
     ===================================================== */

  function getChoiceLabel(
    tableName,
    fieldName,
    value
  ) {

    if (!value) {
      return "";
    }


    var choice =
      new GlideRecord("sys_choice");


    choice.addQuery(
      "name",
      tableName
    );

    choice.addQuery(
      "element",
      fieldName
    );

    choice.addQuery(
      "value",
      value
    );

    choice.addQuery(
      "language",
      "en"
    );

    choice.setLimit(1);

    choice.query();


    if (choice.next()) {

      return (
        choice.getValue("label") ||
        value
      );

    }


    return value;

  }


  /* =====================================================
     CHOICES
     ===================================================== */

  function getChoices(
    tableName,
    fieldName
  ) {

    var result = [];

    var seen = {};


    var choice =
      new GlideRecord("sys_choice");


    choice.addQuery(
      "name",
      tableName
    );

    choice.addQuery(
      "element",
      fieldName
    );

    choice.addQuery(
      "language",
      "en"
    );

    choice.addQuery(
      "inactive",
      false
    );

    choice.orderBy("sequence");

    choice.orderBy("label");

    choice.query();


    while (choice.next()) {

      var value =
        choice.getValue("value");

      var label =
        choice.getValue("label") ||
        value;


      if (
        value &&
        !seen[value]
      ) {

        seen[value] = true;


        result.push({

          value: value,

          label: label

        });

      }

    }


    return result;

  }


  /* =====================================================
     UNIQUE CHOICE
     ===================================================== */

  function addUniqueChoice(
    array,
    value,
    label
  ) {

    if (!value) {
      return;
    }


    var normalized =
      String(value)
        .trim()
        .toLowerCase();


    for (
      var i = 0;
      i < array.length;
      i++
    ) {

      if (
        String(array[i].value)
          .trim()
          .toLowerCase() ===
        normalized
      ) {

        return;

      }

    }


    array.push({

      value: String(value),

      label:
        label ||
        String(value)

    });

  }


  /* =====================================================
     DATE FORMAT
     ===================================================== */

  function formatDateTime(value) {

    if (!value) {
      return "";
    }


    try {

      var gd =
        new GlideDateTime(value);

      return gd.getDisplayValue();

    } catch (e) {

      return value;

    }

  }


  /* =====================================================
     APPLICATION COUNT
     ===================================================== */

  function getApplicationCount(
    opportunitySysId
  ) {

    if (!opportunitySysId) {
      return 0;
    }


    var application =
      new GlideRecord(
        APPLICATION_TABLE
      );


    if (
      !application.isValid() ||
      !application.isValidField(
        "opportunity"
      )
    ) {

      return 0;

    }


    application.addQuery(
      "opportunity",
      opportunitySysId
    );

    application.query();


    return application.getRowCount();

  }


  /* =====================================================
     COMPANIES
     ===================================================== */

  function loadCompanies() {

    var company =
      new GlideRecord(
        COMPANY_TABLE
      );


    if (!company.isValid()) {
      return;
    }


    company.orderBy(
      "company_name"
    );

    company.query();


    while (company.next()) {

      data.companies.push({

        sys_id:
          company.getUniqueValue(),

        name:
          company.getDisplayValue(
            "company_name"
          ) ||
          company.getValue(
            "company_name"
          ) ||
          "Unnamed Company"

      });

    }


    data.companyCount =
      data.companies.length;

  }


  /* =====================================================
     OPPORTUNITIES
     ===================================================== */

  function loadOpportunities() {

    var gr =
      new GlideRecord(
        OPPORTUNITY_TABLE
      );


    if (!gr.isValid()) {
      return;
    }


    gr.orderByDesc(
      "sys_created_on"
    );

    gr.query();


    while (gr.next()) {

      var sysId =
        gr.getUniqueValue();


      var typeValue =
        gr.getValue(
          "opportunity_type"
        ) || "";


      var sourceValue =
        gr.getValue(
          "opportunity_source"
        ) || "";


      var statusValue =
        gr.getValue(
          "status"
        ) || "";


      var typeLabel =
        getChoiceLabel(
          OPPORTUNITY_TABLE,
          "opportunity_type",
          typeValue
        );


      var sourceLabel =
        getChoiceLabel(
          OPPORTUNITY_TABLE,
          "opportunity_source",
          sourceValue
        );


      var statusLabel =
        getChoiceLabel(
          OPPORTUNITY_TABLE,
          "status",
          statusValue
        );


      var applicationCount =
        getApplicationCount(
          sysId
        );


      addUniqueChoice(
        data.opportunityTypes,
        typeValue,
        typeLabel
      );


      addUniqueChoice(
        data.opportunitySources,
        sourceValue,
        sourceLabel
      );


      addUniqueChoice(
        data.statuses,
        statusValue,
        statusLabel
      );


      data.opportunities.push({

        sys_id:
          sysId,

        opportunity_id:
          gr.getValue(
            "opportunity_id"
          ) || "",

        title:
          gr.getValue(
            "opportunity_title"
          ) || "",

        company:
          gr.getDisplayValue(
            "company"
          ) || "",

        company_sys_id:
          gr.getValue(
            "company"
          ) || "",

        type:
          typeLabel,

        type_value:
          typeValue,

        source:
          sourceLabel,

        source_value:
          sourceValue,

        status:
          statusLabel,

        status_value:
          statusValue,

        location:
          gr.getValue(
            "location"
          ) || "",

        ctc:
          gr.getValue(
            "ctc_stipend"
          ) || "",

        minimum_cgpa:
          gr.getValue(
            "minimum_cgpa"
          ) || "",

        eligible_branches:
          gr.getValue(
            "eligible_branches"
          ) || "",

        skills:
          gr.getValue(
            "required_skills"
          ) || "",

        deadline:
          formatDateTime(
            gr.getValue(
              "application_deadline"
            )
          ),

        application_deadline_raw:
          gr.getValue(
            "application_deadline"
          ) || "",

        drive_date:
          formatDateTime(
            gr.getValue(
              "drive_date"
            )
          ),

        drive_date_raw:
          gr.getValue(
            "drive_date"
          ) || "",

        description:
          gr.getValue(
            "job_description"
          ) || "",

        application_count:
          applicationCount

      });


      data.summary.totalApplications +=
        applicationCount;


      var statusForCount =
        String(statusValue)
          .trim()
          .toLowerCase();


      if (
        statusForCount === "open" ||
        statusForCount === "active"
      ) {

        data.summary.openOpportunities++;

      }


      if (
        statusForCount === "closed" ||
        statusForCount === "inactive" ||
        statusForCount === "cancelled" ||
        statusForCount === "canceled"
      ) {

        data.summary.closedOpportunities++;

      }

    }


    data.summary.totalOpportunities =
      data.opportunities.length;


    data.applicationCount =
      data.summary.totalApplications;

  }


  /* =====================================================
     LOAD CHOICES
     ===================================================== */

  function loadChoices() {

    var typeChoices =
      getChoices(
        OPPORTUNITY_TABLE,
        "opportunity_type"
      );


    var sourceChoices =
      getChoices(
        OPPORTUNITY_TABLE,
        "opportunity_source"
      );


    var statusChoices =
      getChoices(
        OPPORTUNITY_TABLE,
        "status"
      );


    typeChoices.forEach(
      function(item) {

        addUniqueChoice(
          data.opportunityTypes,
          item.value,
          item.label
        );

      }
    );


    sourceChoices.forEach(
      function(item) {

        addUniqueChoice(
          data.opportunitySources,
          item.value,
          item.label
        );

      }
    );


    statusChoices.forEach(
      function(item) {

        addUniqueChoice(
          data.statuses,
          item.value,
          item.label
        );

      }
    );

  }


  /* =====================================================
     CREATE
     ===================================================== */

  function createOpportunity(payload) {

    var result = {
      success: false,
      message: ""
    };


    if (!payload) {

      result.message =
        "No opportunity data was received.";

      return result;

    }


    if (
      !payload.opportunity_title ||
      !String(
        payload.opportunity_title
      ).trim()
    ) {

      result.message =
        "Opportunity Title is required.";

      return result;

    }


    if (!payload.company) {

      result.message =
        "Company is required.";

      return result;

    }


    var gr =
      new GlideRecord(
        OPPORTUNITY_TABLE
      );


    if (!gr.isValid()) {

      result.message =
        "Placement Opportunity table could not be found.";

      return result;

    }


    gr.initialize();


    if (
      gr.isValidField(
        "opportunity_id"
      )
    ) {

      gr.setValue(
        "opportunity_id",
        payload.opportunity_id || ""
      );

    }


    gr.setValue(
      "opportunity_title",
      payload.opportunity_title
    );


    gr.setValue(
      "company",
      payload.company
    );


    if (
      gr.isValidField(
        "opportunity_type"
      )
    ) {

      gr.setValue(
        "opportunity_type",
        payload.opportunity_type || ""
      );

    }


    if (
      gr.isValidField(
        "opportunity_source"
      )
    ) {

      gr.setValue(
        "opportunity_source",
        payload.opportunity_source || ""
      );

    }


    if (
      gr.isValidField(
        "status"
      )
    ) {

      gr.setValue(
        "status",
        payload.status || ""
      );

    }


    if (
      gr.isValidField(
        "location"
      )
    ) {

      gr.setValue(
        "location",
        payload.location || ""
      );

    }


    if (
      gr.isValidField(
        "ctc_stipend"
      )
    ) {

      gr.setValue(
        "ctc_stipend",
        payload.ctc_stipend || ""
      );

    }


    if (
      gr.isValidField(
        "minimum_cgpa"
      )
    ) {

      if (
        payload.minimum_cgpa !== "" &&
        payload.minimum_cgpa !== null &&
        payload.minimum_cgpa !== undefined
      ) {

        gr.setValue(
          "minimum_cgpa",
          payload.minimum_cgpa
        );

      }

    }


    if (
      gr.isValidField(
        "eligible_branches"
      )
    ) {

      gr.setValue(
        "eligible_branches",
        payload.eligible_branches || ""
      );

    }


    if (
      gr.isValidField(
        "required_skills"
      )
    ) {

      gr.setValue(
        "required_skills",
        payload.required_skills || ""
      );

    }


    if (
      gr.isValidField(
        "job_description"
      )
    ) {

      gr.setValue(
        "job_description",
        payload.job_description || ""
      );

    }


    if (
      gr.isValidField(
        "application_deadline"
      )
    ) {

      gr.setValue(
        "application_deadline",
        payload.application_deadline || ""
      );

    }


    if (
      gr.isValidField(
        "drive_date"
      )
    ) {

      gr.setValue(
        "drive_date",
        payload.drive_date || ""
      );

    }


    var newSysId =
      gr.insert();


    if (newSysId) {

      result.success = true;

      result.message =
        "Opportunity created successfully.";

      result.sys_id =
        newSysId;

    } else {

      result.message =
        "The opportunity could not be created.";

    }


    return result;

  }


  /* =====================================================
     UPDATE
     ===================================================== */

  function updateOpportunity(payload) {

    var result = {
      success: false,
      message: ""
    };


    if (
      !payload ||
      !payload.sys_id
    ) {

      result.message =
        "Opportunity record was not identified.";

      return result;

    }


    var gr =
      new GlideRecord(
        OPPORTUNITY_TABLE
      );


    if (
      !gr.get(
        payload.sys_id
      )
    ) {

      result.message =
        "Opportunity record could not be found.";

      return result;

    }


    if (
      gr.isValidField(
        "opportunity_id"
      )
    ) {

      gr.setValue(
        "opportunity_id",
        payload.opportunity_id || ""
      );

    }


    if (
      gr.isValidField(
        "opportunity_title"
      )
    ) {

      gr.setValue(
        "opportunity_title",
        payload.opportunity_title || ""
      );

    }


    if (
      gr.isValidField(
        "company"
      )
    ) {

      gr.setValue(
        "company",
        payload.company || ""
      );

    }


    if (
      gr.isValidField(
        "opportunity_type"
      )
    ) {

      gr.setValue(
        "opportunity_type",
        payload.opportunity_type || ""
      );

    }


    if (
      gr.isValidField(
        "opportunity_source"
      )
    ) {

      gr.setValue(
        "opportunity_source",
        payload.opportunity_source || ""
      );

    }


    if (
      gr.isValidField(
        "status"
      )
    ) {

      gr.setValue(
        "status",
        payload.status || ""
      );

    }


    if (
      gr.isValidField(
        "location"
      )
    ) {

      gr.setValue(
        "location",
        payload.location || ""
      );

    }


    if (
      gr.isValidField(
        "ctc_stipend"
      )
    ) {

      gr.setValue(
        "ctc_stipend",
        payload.ctc_stipend || ""
      );

    }


    if (
      gr.isValidField(
        "minimum_cgpa"
      )
    ) {

      gr.setValue(
        "minimum_cgpa",
        payload.minimum_cgpa || ""
      );

    }


    if (
      gr.isValidField(
        "eligible_branches"
      )
    ) {

      gr.setValue(
        "eligible_branches",
        payload.eligible_branches || ""
      );

    }


    if (
      gr.isValidField(
        "required_skills"
      )
    ) {

      gr.setValue(
        "required_skills",
        payload.required_skills || ""
      );

    }


    if (
      gr.isValidField(
        "job_description"
      )
    ) {

      gr.setValue(
        "job_description",
        payload.job_description || ""
      );

    }


    if (
      gr.isValidField(
        "application_deadline"
      )
    ) {

      gr.setValue(
        "application_deadline",
        payload.application_deadline || ""
      );

    }


    if (
      gr.isValidField(
        "drive_date"
      )
    ) {

      gr.setValue(
        "drive_date",
        payload.drive_date || ""
      );

    }


    var updated =
      gr.update();


    if (updated) {

      result.success = true;

      result.message =
        "Opportunity updated successfully.";

      result.sys_id =
        updated;

    } else {

      result.message =
        "The opportunity could not be updated.";

    }


    return result;

  }


  /* =====================================================
     ACTIONS
     ===================================================== */

  if (
    input &&
    input.action === "create"
  ) {

    data.result =
      createOpportunity(
        input.opportunity
      );

    return;

  }


  if (
    input &&
    input.action === "update"
  ) {

    data.result =
      updateOpportunity(
        input.opportunity
      );

    return;

  }


  /* =====================================================
     INITIAL LOAD
     ===================================================== */

  loadChoices();

  loadCompanies();

  loadOpportunities();


})();
(function() {
    var tpoGR = new GlideRecord('x_snc_campus360_campus360_tpo_profile');
    tpoGR.query();
    if (tpoGR.next()) {
        data.tpoName = tpoGR.getValue('tpo_name') || 'MD Ali';
        data.tpoInitials = 'MA';
        data.tpoTitle = tpoGR.getValue('designation') || 'Training & Placement Officer';
        data.tpoOffice = tpoGR.getValue('college_name') || 'CMR Institute of Technology';
    } else {
        data.tpoName = 'MD Ali';
        data.tpoInitials = 'MA';
        data.tpoTitle = 'TPO';
        data.tpoOffice = 'Training & Placement Office';
    }
})();


(function() {
    var tpoGR = new GlideRecord('x_snc_campus360_campus360_tpo_profile');
    tpoGR.query();
    var name = 'MD Ali';
    var title = 'Training & Placement Officer';
    var office = 'CMR Institute of Technology';
    if (tpoGR.next()) {
        name = tpoGR.getValue('tpo_name') || 'MD Ali';
        title = tpoGR.getValue('designation') || title;
        office = tpoGR.getValue('college_name') || office;
    }
    data.tpo = {
        name: name,
        firstName: name,
        initials: 'MA',
        title: title,
        office: office
    };
    data.tpoName = name;
    data.tpoInitials = 'MA';
})();


